function upstreamCell(c){const u=c.legacy_collection_denominators;if(!u)return '<span>Not joined here</span><small>See collection ledger</small>';return Object.entries(u.upstream_collection_counts||{}).map(([k,v])=>`<small><strong>${finite(v)?num(v,k.includes('hours')?1:0):esc(text(v))}</strong> ${esc(human(k))}</small>`).join('');}
function upstreamView(c){const u=c.legacy_collection_denominators;if(!u)return '';return section('Upstream retained collection','These are collection-level records and segments. Their units are different from the selected publication-to-media joins above.',`<div class="panel">${facts(Object.entries(u.upstream_collection_counts||{}).map(([k,v])=>[human(k),esc(finite(v)?num(v,k.includes('hours')?1:0):text(v))]))}${caption(u.scope||'')}${link(u.source_binding?.url,'Open source collection ledger')}${caption('Source SHA-256: '+(u.source_binding?.sha256||'Unrecorded'))}</div>`);}
function filteredChannels(){const q=(S.params.get('q')||'').toLowerCase(),media=S.params.get('media')||'all',rows=channels().filter(c=>JSON.stringify([cname(c),cid(c),c.creator_name,c.creator,c.claimed_labels]).toLowerCase().includes(q)).filter(c=>media==='all'||(media==='retained'?cmedia(c)>0:cmedia(c)===0));return rows.sort((a,b)=>S.params.get('sort')==='name'?cname(a).localeCompare(cname(b)):(cdocs(b)||0)-(cdocs(a)||0));}
