function filteredDocs(){let rows=docs();const q=(S.params.get('q')||'').toLowerCase(),c=S.params.get('context')||'all',o=S.params.get('origin')||'all';return rows.filter(d=>(c==='all'||dchannel(d)===c)&&(o==='all'||origin(d)===o)&&JSON.stringify([d.title,docid(d),d.creator_name,d.creator,d.claimed_labels,d.url,d.source_url]).toLowerCase().includes(q));}
