function render(){document.querySelectorAll('[data-view]').forEach(a=>a.dataset.view===(S.view==='channel'?'channels':S.view)?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));const views={overview:overviewView,channels:channelsView,channel:channelView,corpus:corpusView,analysis:analysisView,paper:paperView,data:dataView,collection:collectionView};$('#main').innerHTML=(views[S.view]||overviewView)();$('#main').setAttribute('aria-busy','false');document.title=(S.view==='channel'?cname(findChannel(S.params.get('channel'))):human(S.view))+' · Dataset workbench · Channeling Atlas';bind();$('#status').textContent=`${human(S.view)} view loaded.`;if(location.hash==='#units')$('#units')?.scrollIntoView();}
