function openInspector(type,id,trigger){S.trigger=trigger;let obj;if(type==='channel')obj={context:findChannel(id),analysis_profile:profile(id)};else if(type==='document')obj={publication:docs().find(d=>docid(d)===id),analysis:modeled(id)};else if(type==='topic')obj=A(analysis().topics).find(t=>String(t.topic_id)===String(id));else if(type==='analysis')obj={frame_sha256:analysis().frame_sha256,summary:analysis().summary,settings:analysis().settings,semantic:analysis().semantic,limitations:analysis().limitations};else if(type==='dataset')obj={schema_version:dataset().schema_version,dataset_version:dataset().dataset_version,frame_sha256:dataset().frame_sha256,summary:dataset().summary,input_bindings:dataset().input_bindings,rights:dataset().rights,limitations:dataset().limitations};else obj=S.modules[type];$('#inspector-title').textContent=type==='document'?'Publication and edition provenance':type==='channel'?'Publisher context provenance':human(type)+' provenance';$('#inspector-body').innerHTML=caption('Public release metadata. Full source text, media and private filesystem locations are excluded.')+`<pre>${esc(JSON.stringify(obj,null,2))}</pre>`;$('#inspector').showModal();}
function bind(){document.querySelectorAll('[data-route],[data-view]').forEach(a=>a.onclick=e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();history.pushState(null,'',a.getAttribute('href'));S.page=1;route();render();$('#main').focus();scrollTo(0,0);});document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>openInspector(b.dataset.inspect,b.dataset.id,b));document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>go(b.dataset.reset));const cf=$('#channel-filters');if(cf)cf.onsubmit=e=>{e.preventDefault();go('channels',{q:$('#context-search').value.trim(),media:$('#media-filter').value,sort:$('#context-sort').value});};const df=$('#corpus-filters');if(df)df.onsubmit=e=>{e.preventDefault();go('corpus',{q:$('#doc-search').value.trim(),context:$('#doc-context').value,origin:$('#doc-origin').value});};if($('#matrix-size'))$('#matrix-size').onchange=()=>{const value=$('#matrix-size').value;history.replaceState(null,'',routeURL('analysis',{matrix:value}));route();render();$('#matrix-size').focus();};if($('#export-channels'))$('#export-channels').onclick=()=>download('publisher-contexts-filtered.csv',csv([['channel_id','name','selected_publications','text_editions','selected_words','unique_encoded_media_joined','joined_media_seconds','youtube_observed_ids_linked_to_documents','youtube_uploaded_total'],...filteredChannels().map(c=>[cid(c),cname(c),cdocs(c),c.text_editions,cwords(c),cmedia(c),cseconds(c),pick(c.youtube_observed_ids_linked_to_documents,c.youtube_observed_ids),pick(c.youtube_uploaded_total,c.youtube_lifetime_total)])]),'text/csv;charset=utf-8');if($('#export-docs'))$('#export-docs').onclick=()=>exportDocs(filteredDocs());if($('#export-context'))$('#export-context').onclick=()=>{const id=S.params.get('channel');download('publisher-'+id+'.json',JSON.stringify({context:findChannel(id),documents:docs().filter(d=>dchannel(d)===id),analysis_profile:profile(id),release_modules:S.manifest.modules},null,2),'application/json');};for(const [id,delta]of [['previous',-1],['next',1]])if($('#'+id))$('#'+id).onclick=()=>{S.page+=delta;render();$('.table-wrap')?.focus();};}
async function load(){try{const response=await fetch('manifest.json',{cache:'no-store'});if(!response.ok)throw Error(`Manifest HTTP ${response.status}`);S.manifest=await response.json();const entries=Object.entries(S.manifest.modules||{});if(!entries.some(([n])=>n==='dataset'))throw Error('Required dataset module is absent from the manifest');if(!crypto?.subtle)throw Error('SHA-256 verification requires HTTPS or localhost');await Promise.all(entries.map(async([name,descriptor])=>{try{if(!safePath(descriptor.file))throw Error('Unsafe module path');if(!/^[a-f0-9]{64}$/i.test(descriptor.sha256||''))throw Error('Missing SHA-256');const r=await fetch(descriptor.file,{cache:'no-store'});if(!r.ok)throw Error(`HTTP ${r.status}`);const b=await r.arrayBuffer();if(finite(descriptor.bytes)&&b.byteLength!==descriptor.bytes)throw Error('Byte length mismatch');const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b))).map(x=>x.toString(16).padStart(2,'0')).join('');if(digest!==descriptor.sha256.toLowerCase())throw Error('SHA-256 mismatch');const value=JSON.parse(new TextDecoder().decode(b));S.modules[name]=name==='collection_plan'?validateCollectionPlan(value):value;}catch(e){S.errors[name]=e.message;}}));for(const[name,d]of entries)if((d.required||name==='dataset')&&!S.modules[name])throw Error(`${human(name)} unavailable: ${S.errors[name]}`);const binding=S.modules.analysis?.dataset_sha256;if((binding&&binding!==S.manifest.modules.dataset.sha256)||(S.modules.analysis?.frame_sha256&&S.modules.analysis.frame_sha256!==S.modules.dataset.frame_sha256)){delete S.modules.analysis;S.errors.analysis='Analysis frame does not match this dataset release';}$('#release-stamp').textContent=`Release built ${S.manifest.generated_at||'at an unrecorded time'}. JSON modules verified before rendering.`;route();render();}catch(e){$('#main').setAttribute('aria-busy','false');$('#main').innerHTML=heading('RELEASE VERIFICATION FAILED','The dataset could not be loaded safely.','Results are withheld until the release files can be verified.')+error(e.message)+`<div class="actions"><button id="retry">Reload release</button><a href="manifest.json">Inspect the manifest</a></div>`;$('#retry').onclick=()=>location.reload();$('#release-stamp').textContent='Release verification failed.';}}
$('#close-inspector').onclick=()=>$('#inspector').close();$('#inspector').addEventListener('close',()=>{if(S.trigger?.isConnected)S.trigger.focus();});addEventListener('popstate',()=>{S.page=1;route();if(S.modules.dataset)render();});load();
